import jax
import jax.numpy as jnp
from jax import lax

def candidate(x):
    c = x[:, :1]
    s = jnp.sum(jnp.exp(x - c), axis=-1, keepdims=True)
    ok = jnp.all(jnp.isfinite(s))

    def fast(args):
        x, c, s = args
        return jnp.exp(x - c) * (1.0 / s)

    def slow(args):
        x, c, s = args
        m = jnp.max(x, axis=-1, keepdims=True)
        e = jnp.exp(x - m)
        return e / jnp.sum(e, axis=-1, keepdims=True)

    return lax.cond(ok, fast, slow, (x, c, s))

