def _blocked(q, k, v, nb):
    seq, hd = q.shape[-2], q.shape[-1]
    bs = seq // nb
    qs = q * (1.0 / jnp.sqrt(jnp.float32(hd)))
    outs = []
    for i in range(nb):
        s0 = i * bs
        e = seq if i == nb - 1 else (i + 1) * bs
        s = jnp.einsum('bhqd,bhkd->bhqk', qs[..., s0:e, :], k[..., :e, :])
        mask = jnp.arange(e)[None, :] <= jnp.arange(s0, e)[:, None]
        s = jnp.where(mask, s, -jnp.inf)
        w = jax.nn.softmax(s, axis=-1)
        outs.append(jnp.einsum('bhqk,bhkd->bhqd', w, v[..., :e, :]))
    return jnp.concatenate(outs, axis=-2)

def candidate(q, k, v):
    return _blocked(q, k, v, 2)

def _blocked(q, k, v, nb):
    seq, hd = q.shape[-2], q.shape[-1]
    bs = seq // nb
    qs = q * (1.0 / jnp.sqrt(jnp.float32(hd)))
    outs = []
    for i in range(nb):
        s0 = i * bs
        e = seq if i == nb - 1 else (i + 1) * bs
        s = jnp.einsum('bhqd,bhkd->bhqk', qs[..., s0:e, :], k[..., :e, :])
        mask = jnp.arange(e)[None, :] <= jnp.arange(s0, e)[:, None]
        s = jnp.where(mask, s, -jnp.inf)
        w = jax.nn.softmax(s, axis=-1)
        outs.append(jnp.einsum('bhqk,bhkd->bhqd', w, v[..., :e, :]))
    return jnp.concatenate(outs, axis=-2)

